// Get effective unit price map for the provided catalog and overrides.
export function getEffectiveItems(priceOverrides = {}, unitItems = UNIT_ITEMS) {
  const items = {};
  for (const [id, item] of Object.entries(unitItems)) {
    items[id] = { ...item, ...priceOverrides[id] };
  }
  return items;
}

function getFixedLengthFeet(item) {
  if (!item?.desc) return null;
  const match = item.desc.match(/(\d+(?:\.\d+)?)'/);
  if (!match) return null;
  const feet = Number(match[1]);
  return Number.isFinite(feet) && feet > 0 ? feet : null;
}

function getLineFactor(line, item) {
  const factor = line.qtyFactor > 0 ? line.qtyFactor : 1;
  if (factor <= 1) return factor;

  // Fixed-length preterm cable items store qtyFactor as requested footage.
  // Convert that footage back into an equivalent count of packaged cable runs.
  if (item?.category === 'Cables' && line.mtlPer === 'E' && line.hrsPer === 'E') {
    const fixedLengthFeet = getFixedLengthFeet(item);
    if (fixedLengthFeet) return factor / fixedLengthFeet;
  }

  return factor;
}

// Calculate assembly cost from current unit prices
export function calcAssembly(aid, priceOverrides = {}, unitItems = UNIT_ITEMS) {
  const asm = ASSEMBLIES[aid];
  if (!asm) return { mtl: 0, lbr: 0 };
  let mtl = 0, lbr = 0;
  for (const line of asm.items) {
    const base = unitItems[line.item];
    if (!base) continue;
    const item = priceOverrides[line.item] ? { ...base, ...priceOverrides[line.item] } : base;
    const div = line.mtlPer === 'C' ? 100 : line.mtlPer === 'M' ? 1000 : 1;
    const lbrDiv = line.hrsPer === 'C' ? 100 : line.hrsPer === 'M' ? 1000 : 1;
    const factor = getLineFactor(line, item);
    mtl += line.qty * item.mtlUnit / div * factor;
    lbr += line.qty * item.hrsUnit / lbrDiv * factor;
  }
  return { mtl: Math.round(mtl * 100) / 100, lbr: Math.round(lbr * 1000) / 1000 };
}

// Snapshot assembly costs at current prices (for locking estimates)
export function snapshotAssemblies(asmIds, priceOverrides = {}) {
  const snap = {};
  for (const aid of asmIds) {
    snap[aid] = calcAssembly(aid, priceOverrides);
  }
  return snap;
}
